effect.shader:
const int TAPS = 12;
void main(){
  vec2 uv = acScreenNorm;
  float rad = radians(angle);
  vec2 dir = vec2(cos(rad), sin(rad));
  vec4 sum = vec4(0.0);
  for (int i = 0; i < TAPS; i++){
    float t = (float(i) / float(TAPS - 1) - 0.5) * amount * mixAmt;
    sum += texture2DCv(inputImg.texture, uv + dir * t);
  }
  gl_FragColor = sum / float(TAPS);
}
